def chart(series,mode,labels=True,H=250):
    W=960; PL=44;PR=6;PT=30;PB=24; n=len(L); slot=(W-PL-PR)/n; gw=slot*.78; bw=gw/len(series)
    isv=mode=='vol'; mx=max(v for s in series for v in s[0][mode])*(1.17 if labels else 1.08)
    Y=lambda v:PT+(1-v/mx)*(H-PT-PB); X=lambda i:PL+i*slot; f=lambda x:f"{x:.1f}"
    s=[]
    s.append(f'<rect x="{f(X(0))}" y="{PT}" width="{f(MCX[0]*slot)}" height="{H-PT-PB}" fill="#ffffff" opacity=".04"/>')
    s.append(f'<rect x="{f(X(MCX[1]+1))}" y="{PT}" width="{f((n-MCX[1]-1)*slot)}" height="{H-PT-PB}" fill="#ffffff" opacity=".04"/>')
    for nm,a,b,col in OPENS:
        x=X(a); w=(b-a+1)*slot
        s.append(f'<rect x="{f(x)}" y="{PT}" width="{f(w)}" height="{H-PT-PB}" fill="{col}" opacity=".10"/>')
        s.append(f'<rect x="{f(x+1)}" y="5" width="{f(w-2)}" height="16" rx="5" fill="{col}"/>')
        lab=nm if len(nm)*6.3+8<=w else nm.split()[0] if len(nm.split()[0])*6.3+6<=w else nm[:2]
        s.append(f'<text x="{f(x+w/2)}" y="16.5" fill="#111" font-size="10" font-weight="700" text-anchor="middle">{lab}</text>')
    wx=X(WIN[0]); ww=(WIN[1]-WIN[0]+1)*slot
    for gi in range(4):
        v=mx*gi/3; y=Y(v)
        s.append(f'<line x1="{PL}" y1="{f(y)}" x2="{W-PR}" y2="{f(y)}" stroke="#252833"/>')
        s.append(f'<text x="{PL-6}" y="{f(y+3.5)}" fill="#8b90a0" font-size="10" text-anchor="end">{(f"{v/1000:.0f}k" if isv else f"{v:.1f}%")}</text>')
    for k,(d,col) in enumerate(series):
        for i,v in enumerate(d[mode]):
            x=X(i)+(slot-gw)/2+k*bw; y=Y(v); op=MCX[0]<=i<=MCX[1]
            s.append(f'<rect x="{f(x)}" y="{f(y)}" width="{f(max(bw-1.5,1.5))}" height="{f(max(H-PB-y,1))}" rx="2" fill="{col}" opacity="{1 if op else .4}"/>')
            if labels:
                t=f"{v/1000:.1f}k" if isv else f"{v:.2f}"
                s.append(f'<text x="{f(x+bw/2)}" y="{f(y-4)}" fill="{"#e7e9ee" if op else "#646a7a"}" font-size="9" font-weight="600" text-anchor="middle">{t}</text>')
    s.append(f'<rect x="{f(wx)}" y="{PT-3}" width="{f(ww)}" height="{H-PT-PB+3}" fill="none" stroke="{WINC}" stroke-width="1.6" stroke-dasharray="5 4" rx="6"/>')
    for i,l in enumerate(L):
        s.append(f'<text x="{f(X(i)+slot/2)}" y="{H-7}" fill="#8b90a0" font-size="9.5" text-anchor="middle">{l}</text>')
    return f'<svg viewBox="0 0 {W} {H}" width="100%" class="bars">{"".join(s)}</svg>'

def meta(d,mode,col):
    v=d[mode][MCX[0]:MCX[1]+1]; Ls=L[MCX[0]:MCX[1]+1]; hi=max(v); lo=min(v)
    fm=(lambda x:f"{x:,} contracts") if mode=='vol' else (lambda x:f"{x:.2f}%")
    return f'During MCX hours: peak <b style="color:{col}">{fm(hi)} at {Ls[v.index(hi)]}</b> · low {fm(lo)} at {Ls[v.index(lo)]} · {hi/lo:.1f}× spread. Faded bars = MCX closed.'
