def strike_rows():
    rows=[]
    def row(con,k,typ,p,unit_d,src=''):
        dist=(p-k) if typ=='CE' else (k-p)
        pct=abs(p-k)/p*100
        if round(pct,1)<=1.0: st,cls='At the money','atm'
        elif dist>0: st,cls='In the money','itm'
        else: st,cls='Out of the money','otm'
        dtxt=(f"{dist:+,.0f}" if unit_d==0 else f"{dist:+.1f}").replace('-','−')
        rows.append(f'<tr><td>{con}</td><td class="num"><b>{k:,} {typ}</b>{src}</td><td class="num">₹{p:,.{unit_d}f}</td><td class="num {cls}">₹{dtxt}</td><td class="num">{pct:.1f}%</td><td>{pill(st,cls)}</td></tr>')
    for k,t in [(7000,'PE'),(8600,'PE'),(8700,'CE'),(8900,'PE'),(9000,'CE'),(9000,'PE')]:
        row('Crude Oil Mini · 15 Oct',k,t,CLR,0,' <span class="sub">watchlist only</span>' if k==8900 else '')
    for k,t in [(290,'PE'),(300,'CE'),(300,'PE'),(310,'CE')]:
        row('NatGas Mini · 23 Oct',k,t,NGR,1)
    return ''.join(rows)

def hourly_rows():
    r=[]
    tags={2:'Asia: Tokyo',3:'Asia: Shanghai/Singapore',9:'Europe: London',10:'Europe follow-through',13:'US pre-market',14:'US data',15:'NYMEX open',20:'NYMEX settlement'}
    for i,l in enumerate(L):
        op=MCX[0]<=i<=MCX[1]; w=WIN[0]<=i<=WIN[1]
        ses='V-Window' if w else ('MCX opens 9:00' if i==MCX[0] else ('MCX open' if op else 'MCX closed'))
        t=tags.get(i,'')
        r.append(f'<tr class="{"" if op else "closed"} {"win" if w else ""}"><td><b>{l}</b></td><td>{ses}{"<br><span class=sub>"+t+"</span>" if t else ""}</td>'
                 f'<td class="num">{c["med"][i]:.2f}%</td><td class="num">{c["avg"][i]:.2f}%</td><td class="num">{c["vol"][i]:,}</td>'
                 f'<td class="num">{g["med"][i]:.2f}%</td><td class="num">{g["avg"][i]:.2f}%</td><td class="num">{g["vol"][i]:,}</td></tr>')
    return ''.join(r)
def bars(items):
